window.SAQ_PAPER_QUESTIONS["2022-1-pah"]=[{"number":1,"title":"","stemText":"A 55 year old man has presented with chest pain and dizziness.\nHis ECG is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State the pathology demonstrated on the ECG, with 3 supportive features. (4 marks) Pathology Supportive features 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 3 potential causes of this pathology. (3 marks)\n1) 2) 3)\nHis vital signs are:\n\nGCS\n\nBP\n80/45 mmHg O2 sats 98% room air"},{"id":"c","label":"Part C","prompt":"State 4 key aspects of your primary management strategy. (4 marks)\n1) 2) 3) 4)"}],"propPages":["asset:img36b833e575c989766c"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Tachycardia 150 approx</div><div class=\"answer-line\">Wide complex 160ms approx.</div><div class=\"answer-line\">regular</div><div class=\"answer-line\">Presence fusion beats</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypokalaemia</div><div class=\"answer-line\">Cardiomyopathy / fibrosis</div><div class=\"answer-line\">Drug toxicity eg digoxin, TCA</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Consent electrical cardioversion</div><div class=\"answer-line\">Apply pads</div><div class=\"answer-line\">Analgesia / sedation – something sensible</div><div class=\"answer-line\">100-200J</div><div class=\"answer-line\"><strong>Sync </strong></div><div class=\"answer-line\">Correct underlying cause</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"An 8 year old boy has been brought to the ED with a 3 day history of a limp.","parts":[{"id":"a","label":"Part A","prompt":"List 6 differential diagnoses that you would consider. For each, give a cardinal assessment finding (history, examination or investigation) that would suggest the diagnosis. (12 marks) Diagnosis Cardinal assessment finding"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Perthes – x-ray loss femoral head height, fragmented epiphysis</td><td>SUFE – x-ray slipped femoral head, Trethowan’s sign</td></tr><tr><td><strong>Septic arthritis</strong> – fever, raised inflammatory markers, loss ROM</td><td>Transient synovitis – well child, recent viral illness</td></tr><tr><td>Fracture – seen on xray, Hx trauma</td><td>Haematological eg leukaemia – leukaemoid blood film – raised WCC blasts</td></tr><tr><td>Many others likely OK</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 75 year old woman has presented with confusion and a decreased level of consciousness.\nShe lives in a nursing home. A slice from a CT scan of her head is given below.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis from the CT scan and give 4 relevant radiographical features. (6 marks) Diagnosis (2 marks) Relevant radiographical features (4 marks) 1) 2) 3) 4) The patient’s son has arrived. He is the next of kin for the patient."},{"id":"b","label":"Part B","prompt":"State 4 key aspects of the patient’s history you will seek to clarify from the son. (4 marks) 1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"State 2 key messages you would aim to convey to the son regarding his mother’s current\ncondition. (2 marks) 1) 2)"}],"propPages":["asset:img3784ad32d5b5f44817"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Isodense collection left side subdural anterior to posterior</div><div class=\"answer-line\">Midline shift</div><div class=\"answer-line\">Loss sulci</div><div class=\"answer-line\">Subfalcine herniation</div><div class=\"answer-line\">Accept some loss grey/white differentiation</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Quality of life</div><div class=\"answer-line\">Previous wishes</div><div class=\"answer-line\">Other comorbidities</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Life-threatening condition</div><div class=\"answer-line\">Explain pathology – treatment options surgery vs no surgery</div><div class=\"answer-line\">Discussion end-of-life cares</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 45 year old Indigenous man has presented to hospital with difficulty breathing.\nHe has a history of type 2 diabetes mellitus complicated by end-stage renal failure for which he\nundergoes haemodialysis 3 times per week.","parts":[{"id":"a","label":"Part A","prompt":"List 6 investigations you would perform on this man. For each, state how it will assist in your assessment. (6 marks) 1) 2) 3) 4) 5) 6) You have concluded that the patient needs to stay in hospital for urgent treatment. A short time later, he has expressed a desire to leave."},{"id":"b","label":"Part B","prompt":"State 5 features of your response to this situation. (5 marks)\n1) 2) 3) 4) 5)"},{"id":"c","label":"Part C","prompt":"List 5 features of culturally competent patient-centred care as per the ACEM Statement on\nCultural Safety in the Emergency Department. (5 marks) 1) 2) 3) 4) 5)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>CXR – diagnosis eg LVF vs infection vs other eg PTX</td><td>Hb – exclude anaemia contributing to SOB</td></tr><tr><td>ABG – define pCO2 which may indicate need for NIV eg in COPD</td><td>BC – use in suspected sepsis to culture bacteria for later antimicrobial targeted therapy</td></tr><tr><td>ECG – exclude STEMI as cause SOB – might need PCI</td><td><strong>K – exclude life-threatening hyperK which could co-exist with APO in missed dialysis </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Explain diagnosis, intended Rx and need to stay</div><div class=\"answer-line\">Find out why he wants to go</div><div class=\"answer-line\">Establish whether he is competent - understands illness and treatment options?</div><div class=\"answer-line\">Attempt to address his issues eg provide support person / food etc</div><div class=\"answer-line\">Involve family / NOK</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Take a cultural history with pts and care-givers</div><div class=\"answer-line\">Incorporate diverse health beliefs in to ED care</div><div class=\"answer-line\">All patients have access to support people according to cultural needs</div><div class=\"answer-line\">All patients given opportunity to speak to cultural/religious representative of their choosing</div><div class=\"answer-line\">Professional interpreter</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 60 year old woman has presented with left sided weakness of 4 hours duration.\nYou are considering the diagnosis of acute ischaemic stroke.","parts":[{"id":"a","label":"Part A","prompt":"List 5 differential diagnoses apart from ischaemic stroke. For each, list an assessment\nfeature from either history or examination that would support that diagnosis. (10 marks) Differential Diagnosis Assessment feature (Hx or Ex) Your assessment is consistent with an acute ischaemic stroke."},{"id":"b","label":"Part B","prompt":"List 4 features of your further assessment that would make the patient suitable for\nendovascular clot retrieval. (4 marks) 1) 2) 3) 4) The decision has been made to perform endovascular clot retrieval following thrombolysis. A short time later, whilst waiting to go to the interventional radiology suite, the patient has a brief, self-limiting seizure."},{"id":"c","label":"Part C","prompt":"List 4 causes of the seizure you would seek to exclude. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Intracranial haemorrhage – headache, anti-coagulants</td><td>Migraine – preceding aura, Hx migraine</td></tr><tr><td>Hypoglycaemia – insulin use, no food</td><td>Functional weakness – Hx mental health disorders, previous functional disorders eg seizures</td></tr><tr><td>Todd’s paresis – post-ictal ie just had a seizure, bitten tongue etc</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Proximal clot</div><div class=\"answer-line\">Small core, large penumbra</div><div class=\"answer-line\">NIHSS &gt;= 6</div><div class=\"answer-line\">Modifies Rankin score &lt;= 2 – or something about QOL</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hypoxia – eg aspiration</div><div class=\"answer-line\">Hypotension eg arrhythmia</div><div class=\"answer-line\">Known seizure disorder</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"A 24 year old man has been brought to the ED after being bitten by a snake in his garden.","parts":[{"id":"a","label":"Part A","prompt":"List 4 features of your initial history or examination that would necessitate the\nadministration of anti-venom prior to any laboratory results becoming available. (4 marks) 1) 2) 3) 4) His coagulation profile is provided below.\n\nINR\n>10.0 (0.9 - 1.2) PT >120s (9 - 13)\n\nAPTT\n>200s (25 - 38) Fibrinogen <0.4g/L (2.0 - 4.5)"},{"id":"c","label":"Part C","prompt":"State your conclusion from the coagulation profile. (1 mark)"},{"id":"d","label":"Part D","prompt":"List 3 snakes that could produce this result. (3 marks)\n1) 2) 3)"},{"id":"e","label":"Part E","prompt":"State 2 considerations when determining which anti-venom to administer. (2 marks)\n1) 2)"},{"id":"f","label":"Part F","prompt":"List 2 side-effects of anti-venom administration. (2 marks)\n1) 2)"}],"propPages":[],"questionPages":[],"answerPages":[],"removedNonQuestionResponseFragments":["dimer >128.0mg/L (0.02 - 0.49)"],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Collapse</div><div class=\"answer-line\">Vomiting / abdo pain</div><div class=\"answer-line\">Weakness / paralysis / signs neurotoxicity</div><div class=\"answer-line\">Significant bleeding</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Complete VICC</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Taipan</div><div class=\"answer-line\">Tiger</div><div class=\"answer-line\">Brown</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Geography - &gt;2 snakes = polyvalent antivenom</div><div class=\"answer-line\">Clinical syndrome – eg VICC means not black snake for example</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Anaphylaxis</div><div class=\"answer-line\">Serum sickness</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"You have been tasked to address your department’s short stay ward performance. In the last month, the percentage of short stay ward admissions with an ELOS (Emergency Length of\nStay) of less than 4hrs has been 25%. Your hospital’s target is 80%.","parts":[{"id":"a","label":"Part A","prompt":"List 5 relevant pieces of information you will need in your assessment of this situation.\nProvide justification for each. (5 marks) 1) 2) 3) 4) 5)"},{"id":"b","label":"Part B","prompt":"List 6 strategies that might help improve this performance. Provide relevance for each\nstrategy. (6 marks) 1) 2) 3) 4) 5) 6)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Overall ELOS – is it just SSW with a problem or is there whole system issue</td><td>POST / ramping time – are patients waiting hours before even being assessed in a cubicle</td></tr><tr><td>Waiting time – are all patients waiting too long to be seen</td><td>Overall daily attendance vs usual – has there been an increase in activity</td></tr><tr><td>SSW access block – are patients waiting to even get in to SSW due to it being full</td><td>SSW LOS – are we admitting the wrong patients to SSW who then occupy beds</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>- All SSW admissions must be approved by senior clinician – might avoid inappropriate admissions</td><td>which stay too long and occupy beds</td></tr><tr><td>- criteria led discharge from SSW – allows nurses to facilitate DC to free up beds when doctor not</td><td>available</td></tr><tr><td>- dedicated SSW team / regular SSW rounds – allow more timely discharge to free up beds</td><td>- direct admission to SSW from triage where certain clinical criteria are met eg low risk toxicological</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"A 10 day old girl has been brought to the ED with jaundice.","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential causes. For each, state a specific assessment finding (history, examination\n• r investigation) that would suggest its presence. (12 marks)\nCause Specific assessment finding (Hx, Ex or Ix)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Breast milk jaundice – began day 4-7, breast fed child, otherwise well</td><td><strong>Sepsis</strong> – fever, localising symptoms or signs</td></tr><tr><td>Biliary atresia – conjugated hyperbilirubinemia, USS bile ducts confirming</td><td>Hypothyroidism – reduced T3/4</td></tr><tr><td>Rbc membrane defects eg sickle cell anaemia – genetic testing, Hb EPP</td><td>Hepatitis – Hep B/C testing</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 75 year old woman has presented with abdominal pain.\nAn x-ray of her abdomen is provided below.","parts":[{"id":"a","label":"Part A","prompt":"State your conclusion, supported by 3 radiographical findings. (4 marks) Conclusion Radiographical findings 1) 2) 3)"},{"id":"b","label":"Part B","prompt":"State 4 features of your examination, including the relevance of each. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List and justify 4 further investigations you will perform. (4 marks)\n1) 2) 3) 4)\nPAH 2022.1 trial SAQ paper\nPART 2\nQuestions 10 - 18\n1 hour"}],"propPages":["asset:img0af4acc913d0ad4c35"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Multiple dilated loops small bowel</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Valvulae conniventes</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Central location</div><div class=\"answer-line\">Minimal large bowel gas</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>Vital signs</strong> – define degree of fluid loss / third spacing / shock – requirement for resuscitation</div><div class=\"answer-line\">Hernial orifices – look for cause of SBO</div><div class=\"answer-line\">Scars abdo wall – indicates likelihood of adhesions as cause</div><div class=\"answer-line\">Presence of peritonism – indicates chance of perforation as complication – would need urgent</div><div class=\"answer-line\">laparotomy</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">CT abdo – look for transition point / presence masses/tumours</div><div class=\"answer-line\">VBG – look for lactic acidosis which might indicate ischaemic bowel as complication</div><div class=\"answer-line\">Serum electrolytes – Na/K – electrolyte loss in third spacing in to bowel, might need replacement</div><div class=\"answer-line\">Renal function – exclude pre-renal renal failure due to dehydration</div><div class=\"answer-line\">Coags – if on warfarin define coagulopathy prior to surgery</div><div class=\"answer-line\">G+H – have cross matched blood ready pre-op</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 34 year old man has presented with fever and difficulty breathing following a 6 day history of cough and rhinorrhea.\nHe weighs 136kg but has never seen a doctor.\nHis chest x-ray is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 radiographical abnormalities on the x-ray. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List and justify 4 investigations you could perform to find the cause of this presentation. (4 marks) 1) 2) 3) 4) The patient’s vital signs are:\n\nHR\n130 /min\n\nBP\n110/70 mmHg\n\nRR\n/min O2 sats 88% 15L O2 via non-rebreather mask You are planning to intubate the patient."},{"id":"c","label":"Part C","prompt":"State 4 difficulties you might encounter in establishing effective mechanical ventilation. Outline how you will manage each difficulty. (4 marks) 1) 2) 3) 4)"}],"propPages":["asset:imga30baddd0512aa5ef9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Bilateral</div><div class=\"answer-line\">Patchy with areas confluence</div><div class=\"answer-line\">Consolidation</div><div class=\"answer-line\">Symmetrical</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>COVID swab</strong> RAT/PCR – determine whether COVID is cause – isolate etc</div><div class=\"answer-line\">BC – aim to culture organism to narrow antimicrobial spectrum in 1-2 days</div><div class=\"answer-line\">Urine Strep Ag – can quickly identify Strep to allow focussed Abs</div><div class=\"answer-line\">Chlamydia / legionella titre – look for atypical infection</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Difficulty oxygenating – FiO2 1.0, increase PEEP start 10cm H2O aim for pO2 &gt;60mmHg</div><div class=\"answer-line\">Large abdomen causing pressure on thorax resulting in high pressure requirements – sit pt up</div><div class=\"answer-line\">Poor lung compliance due to widespread infection resulting in ARDS – use 6ml/kg tidal volume then</div><div class=\"answer-line\">increase RR until normal CO2 achieved</div><div class=\"answer-line\">Inadequate sedation resulting in ventilator dysychrony – use higher doses of sedation than usual due</div><div class=\"answer-line\">to high BMI, may need to paralyse pt</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"An 82 year old man has presented with sudden onset abdominal pain preceding a collapse.\nHe has a background of hypertension and heavy smoking. An image from a bedside ultrasound scan of his epigastrium is provided below. The probe was\n• rientated in a transverse plane.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis supported by two abnormalities from the image. (3 marks) Diagnosis Abnormalities 1) 2)"},{"id":"b","label":"Part B","prompt":"List 2 other findings from your further ultrasound examination that might influence the\npatient’s management. Explain the significance of each. (2 marks) 1) 2)"},{"id":"c","label":"Part C","prompt":"List 2 advantages and 2 disadvantages of performing a CT scan on this patient. (4 marks)\nAdvantages 1) 2) Disadvantages 1) 2) The patient has the following vital signs:\n\nGCS\nE3 V5 M6 Pulse /min\n\nBP\n83/45 mmHg\n\nRR\n/min O2 sats 98% 6L O2 via Hudson mask"},{"id":"d","label":"Part D","prompt":"State 3 features of your management strategy for this patient. (3 marks)\n1) 2) 3)"}],"propPages":["asset:img49fb46012df34c8b30"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Abdominal aortic aneurysm – ruptured based on Hx</div><div class=\"answer-line\">Approx. 8cm transverse measurement abdominal aortic aneurysm</div><div class=\"answer-line\">Large amount mural thrombus</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Supra-renal vs infra-renal based on longitudinal view – requirement for supra-renal cross clamp in</div><div class=\"answer-line\">OT – greater morbidity</div><div class=\"answer-line\">Free fluid in peritoneum – indicates massive blood loss from rupture and more urgent OT</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Option</th><th>Advantage</th><th>Disadvantage</th></tr></thead><tbody><tr><td>Defines supra-renal vs infra-renal for operative planning</td><td>Defines possible suitability for stent vs open management</td><td>Takes time which might cause clinical deterioration – risk of death</td></tr><tr><td>Requires contrast which could damage kidneys (in a pt who is potentially about to have</td><td>blood supply to kidneys interrupted in OT)</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Analgesia – IV fentanyl 25mcg boluses careful titration to pain</div><div class=\"answer-line\">No fluid unless systolic &lt;80mmHg or poor mentation, then blood only</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 4 month old girl has been brought to the ED with a 24 hour history of fevers.\nShe is pale and mottled. On transfer of the child to the ED trolley, it is apparent that the child is not breathing and has no palpable pulse. Heart rate monitoring shows a sinus rhythm at 40 beats per minute.","parts":[{"id":"a","label":"Part A","prompt":"State 3 immediate measures you would initiate. (3 marks)\n1) 2) 3)"},{"id":"b","label":"Part B","prompt":"List 4 potential reversible factors in this child’s presentation. State how you will address each. (4 marks) 1) 2) 3) 4) Your initial management is successful and you are attending to the ongoing management of the patient and her parents."},{"id":"c","label":"Part C","prompt":"State 4 key aspects of your discussion with the parents that will affect your further\nmanagement. Explain the relevance of each. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">CPR</div><div class=\"answer-line\">Compressions 100/min</div><div class=\"answer-line\">15 compressions :2 breaths</div><div class=\"answer-line\">IV adrenaline 10mcg/kg</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Hypoxia – aim for early intubation with FiO2 1.0</div><div class=\"answer-line\">Hypoglycaemia – IV 2-5ml/kg 10% dextrose</div><div class=\"answer-line\">Hypovolemia (sepsis) – IV N/S 20ml/kg bolus</div><div class=\"answer-line\">Hypothermia – external warming, warm IV fluids</div><div class=\"answer-line\">Might accept tamponade but other Ts – they don’t fit</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Hx of illness ie localising symptoms sepsis – will direct Ix and anti-biotic choice</div><div class=\"answer-line\">Allergies – avoid these drugs eg Abs</div><div class=\"answer-line\">Immunizations – unimmunized will need broader cover Abs</div><div class=\"answer-line\">PMHx – eg congenital heart/lung problems that will complicate management eg limit fluid in CCF</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"An 82 year old woman has been brought to the ED after a syncopal event at home.\nShe currently has no symptoms.","parts":[{"id":"a","label":"Part A","prompt":"List 6 potential causes of cardiac syncope. For each, give a diagnostic assessment finding (history, examination or bedside investigation) that would support its presence. (6 marks) Cardiac cause Diagnostic assessment finding"},{"id":"b","label":"Part B","prompt":"List 5 causes of syncope that can be safely managed with discharge from the ED and\n• utpatient follow up. For each, state a feature from your history that would support its\npresence. (5 marks) Cause Historical feature"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Complete heart block – presence of bifascicular block on ECG in ED</td><td>VT – Hx MI, frequent non-sustained VT in the ED</td></tr><tr><td>Torsades de pointes – long QT on ECG</td><td>Severe AS – loud harsh ESM with poor volume carotid pulse</td></tr><tr><td>HOCM – exercise induced syncope, ECG features – LVH with dagger Q waves lateral leads</td><td>ARVC – epsilon wave on ECG, RBBB, family Hx sudden death</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Cough syncope – coughing fit prior to syncope</td><td>Will accept one other situational syncope eg micturition – occur during micturition</td></tr><tr><td>Orthostatic hypotension – recurrent pre-syncope/syncope on standing from lying position</td><td>Accept one other cause of orthostatic – eg dehydration, drugs</td></tr><tr><td>Vasovagal syncope – preceded by stressful event eg blood taking</td><td></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"An 18 year old female has presented with a deformed left ankle following a surfing accident. There is a large wound overlying her ankle, with bone on view. An x-ray of her left ankle is shown below.","parts":[{"id":"a","label":"Part A","prompt":"State the diagnosis and provide 3 radiographic abnormalities. (4 marks) Diagnosis Radiographic abnormalities 1) 2) 3) You have decided to administer prophylactic antibiotics."},{"id":"b","label":"Part B","prompt":"List 2 antibiotics you would use. For each, state the antimicrobial spectrum you intend to cover. (2 marks) 1) 2)"},{"id":"c","label":"Part C","prompt":"State 5 additional components of your management. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":["asset:img2aacfdd3f56ab98c77"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Weber C distal fibula # / dislocation</div><div class=\"answer-line\">Oblique fracture distal fibula</div><div class=\"answer-line\">Lateral displacement talus (wide medial joint space)</div><div class=\"answer-line\">Widened syndesmosis distal tib-fib</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Cefazolin  - gram positive ie Staph aureus</td><td>ciprofloaxacin – water borne organisms eg Vibrio vulnificus</td></tr><tr><td>cefipime</td><td>prob other acceptable regimes</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – IV fentanyl 25mcg q10 min prn</div><div class=\"answer-line\">Sedation</div><div class=\"answer-line\">reduction</div><div class=\"answer-line\">Plaster immobilisation – short leg</div><div class=\"answer-line\">Othopaedic referral for ORIF</div><div class=\"answer-line\">Elevate</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"A 54 year old man has presented with a 6 hour history of a painful penile erection. He has multiple co-morbidities and has brought in his Webster pack of regular medications.","parts":[{"id":"a","label":"Part A","prompt":"List 4 classes of drugs that can increase the risk of priapism. (4 marks)\n1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"Aside from drugs, list 4 other causes of priapism. (4 marks) 1) 2) 3) 4) A cavernosal blood gas is provided below:\n\npH\n7.2\n\npCO2\nmmHg\n\npO2\nmmHg"},{"id":"c","label":"Part C","prompt":"State the clinical significance of this result. (2 marks)"},{"id":"d","label":"Part D","prompt":"State 4 components of your management of the patient. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>Antipsychotics &amp;</td><td>risperidone, olanzapine, clozapine, chlorpromazine, quetiapine, sertraline, citalopram,</td></tr><tr><td>Antidepressants</td><td>escitalopram, lithium, fluoxetine, trifluoperazine, pericyazine</td></tr><tr><td>Vasoactive erectile agents</td><td>alprostadil, papaverine</td></tr><tr><td>α-adrenergic receptor</td><td>doxazosin, tamsulosin, terazosin, prazosin</td></tr><tr><td colspan=\"2\">antagonists</td></tr><tr><td>Antihypertensives</td><td>hydralazine, propranolol</td></tr><tr><td>Anticoagulants</td><td>heparin, warfarin</td></tr><tr><td>Hormones</td><td>testosterone, gonadotropin-releasing hormone</td></tr><tr><td colspan=\"2\"><strong>Medicines that have been reported to cause priapism</strong> 3, 4.</td></tr><tr><td>Phosphodiesterase type 5</td><td>sildenafil, tadalafil</td></tr><tr><td colspan=\"2\">inhibitors</td></tr><tr><td>Medicines used for ADHD</td><td>methylphenidate, atomoxetine</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Lots:</div><div class=\"answer-line\">Haematological – eg sickle cell, spherocytosis</div><div class=\"answer-line\">Malignancy – eg leukaemia</div><div class=\"answer-line\">Neurological – eg MS</div><div class=\"answer-line\">Infection – malaria</div><div class=\"answer-line\">Metabolic – gout, amyloidosis</div><div class=\"answer-line\">High flow – fistula</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Low flow (ischaemic cause)</div><div class=\"answer-line\">Will require management to decrease chance impotence</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Analgesia – eg IV fentanyl 25mcg q10min prn</div><div class=\"answer-line\">Local anaesthesia – dorsal block / penile block</div><div class=\"answer-line\">Aspiration / flush – large bore cannula</div><div class=\"answer-line\">Injection alpha agonist eg phenylephrine / adrenaline</div><div class=\"answer-line\">Urology referral</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 68 year old female has self-presented to your ED with 6 hours of left sided chest pain.\nHer ECG is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 3 abnormalities shown on the ECG and provide the most likely diagnosis. (4 marks)\nECG abnormalities 1) 2) 3) Diagnosis"},{"id":"b","label":"Part B","prompt":"State 2 additional investigative abnormalities that would support your diagnosis.\n(2 marks) 1) 2) The patient has ongoing chest pain.\nHer vital signs are:\n\nGCS\n\nBP\n170/90 mmHg\n\nRR\n/min O2 sats 99% room air"},{"id":"c","label":"Part C","prompt":"State 6 components of your management. (6 marks)\n1) 2) 3) 4) 5) 6)"}],"propPages":["asset:img1844128e33880c0ee9"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">First degree HB</div><div class=\"answer-line\">ST depression V2-V5</div><div class=\"answer-line\">Large R wave V2</div><div class=\"answer-line\">Posterior STEMI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Bedside echo with RWMA</div><div class=\"answer-line\">Positive troponin also accept</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Aspirin 300mg po</div><div class=\"answer-line\">Clopidogrel 300mg or ticagrelor 180mg</div><div class=\"answer-line\">Heparin 5000 U or so</div><div class=\"answer-line\">Analgesia fentanyl 25mcg q10 min prn</div><div class=\"answer-line\">GTN infusion – aim pain free. BP 120 systolic</div><div class=\"answer-line\"><strong>Cardiology for PCI </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A 36 year old woman has presented with a severe exacerbation of asthma.\nHer treatment to date has included: Continuous salbutamol via nebuliser Ipratropium via nebuliser - 3 doses 500mcg\nHydrocortisone 200mg IV\nMgSO4 10mmol IV\nHer vital signs are:\n\nGCS\nE3 V4 M6 Pulse 140 /min\n\nBP\n90/45 mmHg\n\nRR\n/min O2 sats 82% 15L O2 via nebuliser mask She is getting increasingly tired and you are planning to intubate the patient.","parts":[{"id":"a","label":"Part A","prompt":"State 4 goals of your preparation for intubation and how you will achieve each goal.\n(4 marks) 1) 2) 3) 4)"},{"id":"b","label":"Part B","prompt":"State 4 modifications to a standard RSI that you would employ. Provide justification for\neach. (4 marks) 1) 2) 3) 4) Your registrar wants to perform the intubation."},{"id":"c","label":"Part C","prompt":"List 4 methods you could employ to confirm endotracheal placement of the tube by the\nregistrar. (4 marks) 1) 2) 3) 4) Intubation was successful and mechanical ventilation has been established. Shortly after, the ventilator is displaying a high pressure alarm."},{"id":"d","label":"Part D","prompt":"List 3 likely causes of a high pressure alarm in this situation. For each, provide the\nimmediate specific management. (6 marks) Cause of high pressure alarm Management"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Improve pre-oxygenation</strong> – use NIV Fio2 1.0 with PEEP 10cm H2O</div><div class=\"answer-line\"><strong>BP optimization</strong> – IV fluid N/S 1L stat</div><div class=\"answer-line\">Maximise bronchodilator therapy – IV adrenaline infusion start at 5-10 mcg/min</div><div class=\"answer-line\">Optimise position – sitting up for pre-ox, pillow in situ,</div><div class=\"answer-line\">Others</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Use ketamine for induction (as bronchodilator) 100mg</div><div class=\"answer-line\">Bag through apnoea – aim to prevent hypoxia</div><div class=\"answer-line\">Use largest possible ET tube to maximise flow / minimise resistance – limit peak pressure ventilator</div><div class=\"answer-line\">Induce sitting up – recline on induction – goal to optimise oxygenation/ventilaton as much as</div><div class=\"answer-line\">possible</div><div class=\"answer-line\">Others</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Visualisation on video screen</div><div class=\"answer-line\">Use stethoscope for breath sounds</div><div class=\"answer-line\">ET capnography</div><div class=\"answer-line\">Fogging tube</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td><strong>Tension pneumothorax</strong> – thoracostomy and ICC</td><td><strong>Dynamic hyperinflation</strong> – disconnect, allow exhalation, tolerate hypercapnoea</td></tr><tr><td>Dyssynchrony – sedation and paralysis</td><td>Others likely</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 5 year old boy has been brought to the ED after sustaining hot water burns.\nHe weighs 20kg.\nA clinical photograph is provided below.","parts":[{"id":"a","label":"Part A","prompt":"List 4 descriptive features of the burn evident on the clinical photograph. (4 marks)\n1) 2) 3) 4) Below is a diagram for estimating the surface area of burns in paediatric patients. Each area refers to both the anterior and posterior parts delineated, except the trunk as explained in the diagram."},{"id":"b","label":"Part B","prompt":"Assign percentages to each of the allocated areas. (4 marks) A B C D Your assessment reveals the patient has 15% total body surface area burns."},{"id":"c","label":"Part C","prompt":"Provide the details of your fluid resuscitation strategy. (2 marks)"},{"id":"d","label":"Part D","prompt":"State 3 key aspects of your management, other than IV fluid therapy. (3 marks)\n1) 2) 3)"},{"id":"e","label":"Part E","prompt":"List 4 features of your history or examination that would raise suspicion of non-accidental injury. (4 marks) 1) 2) 3) 4)\nPAH 2022.1 trial SAQ paper\nPART 3\nQuestions 19 - 27\n1 hour"}],"propPages":["asset:img14ee316a5f0f9761d3","asset:imga4f80ff1eaf3d3c52a"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Burned areas upper back, shoulders and proximal upper limbs</div><div class=\"answer-line\">Blistering</div><div class=\"answer-line\">Large areas desquamation</div><div class=\"answer-line\">Mostly superficial partial thickness</div><div class=\"answer-line\">Alert child, well perfused</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">A – 18</div><div class=\"answer-line\">B – 14</div><div class=\"answer-line\">C – 9</div><div class=\"answer-line\">D – 18</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Parkland – paeds</div><div class=\"answer-line\">3-4ml/kg*TBSAburns over 24hrs, half first 8 hrs plus maintenance</div><div class=\"answer-line\">Hartmanns</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"><strong>Analgesia</strong> (Morphine/fentanyl – doses/routes)</div><div class=\"answer-line\">First aid measures – cool running water</div><div class=\"answer-line\">ADT up to date</div><div class=\"answer-line\">Burns unit referral given extent</div><div class=\"answer-line\">Dressings as per burns unit</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">Inconsistent story for how it happened</div><div class=\"answer-line\">Other injuries evident eg lots of bruising different ages</div><div class=\"answer-line\">Not wanting to go to caregiver</div><div class=\"answer-line\">Recurrent presentations with odd injuries to hospitals</div><div class=\"answer-line\">Delayed presentation</div><div class=\"answer-line\">others</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 2 year old girl has been referred to the ED by her GP. She has ongoing left ear pain despite being prescribed oral antibiotics for acute otitis media 4 days ago.","parts":[{"id":"a","label":"Part A","prompt":"List 4 accepted indications for oral antibiotic therapy in acute otitis media. (4 marks)\n1) 2) 3) 4) A clinical photograph of the child is given below."},{"id":"b","label":"Part B","prompt":"State the diagnosis demonstrated, including 3 supportive findings. (4 marks) Diagnosis Supportive findings 1) 2) 3)"},{"id":"c","label":"Part C","prompt":"State 3 key aspects of your management. (3 marks)\n1) 2) 3)"}],"propPages":["asset:img280ca9340e1bb7e391"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Immunocompromised</div><div class=\"answer-line\">ATSI</div><div class=\"answer-line\">Only hearing ear</div><div class=\"answer-line\">Cochlear implant</div><div class=\"answer-line\">Suppurative complication eg mastoiditis</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Erythema posterior to auricle</div><div class=\"answer-line\">Oedema post-auricular</div><div class=\"answer-line\">Ear bulging outward</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Analgesia – drug, route, dose</div><div class=\"answer-line\"><strong>IV antibiotics eg flucloxacillin plus ceftriaxone </strong></div><div class=\"answer-line\"><strong>Admission ENT for observation +/- imaging +/- surgery </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"You have been called to see an elderly man in your short stay ward. He has become unwell during the administration of a packed red blood cell transfusion for symptomatic anaemia.","parts":[{"id":"a","label":"Part A","prompt":"List 4 distinct acute transfusion reactions. For each, include the key assessment finding/s (history, examination or investigation) that will support its presence. (8 marks) Cause Key assessment finding/s (Hx, Ex, Ix)"},{"id":"b","label":"Part B","prompt":"List 4 quality control processes in the administration of blood products that aim to\ndecrease the incidence of significant transfusion reactions. (4 marks) 1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Allergic – urticaria, wheezing, angio-oedema</td><td>Volume overload (TACO) – SOB, crackles on examination, raised JVP</td></tr><tr><td>Febrile, non-haemolytic – fever, chills, no other signs, normal haemodyamics</td><td>Acute haemolysis (ABO incompatibility) – fever, tachycardia, shock, DIC</td></tr><tr><td>TRALI – within 6 hrs – fever, tachycardia, hypoxia, pulmonary oedema</td><td>also accept bacterial sepsis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Multiple point pt identity checks in blood bank</div><div class=\"answer-line\">Multiple nursing check pt identity at bedside</div><div class=\"answer-line\">Frequent obs with onset of transfusion</div><div class=\"answer-line\">Strict controls about transport and storage of components eg temperature</div><div class=\"answer-line\">Many others will be OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 2 year old girl has fallen from a slide in a playground.\nShe has an isolated left arm injury. Her x-rays are provided below.","parts":[{"id":"a","label":"Part A","prompt":"Describe and name the injury shown. (3 marks)"},{"id":"b","label":"Part B","prompt":"State 4 key aspects of your examination. Include the relevance of each. (4 marks)\n1) 2) 3) 4)"},{"id":"c","label":"Part C","prompt":"List 3 options for analgesia in this patient. (3 marks)\n1) 2) 3)"},{"id":"d","label":"Part D","prompt":"State 2 key aspects of your management, apart from analgesia. (2 marks)\n1) 2)"}],"propPages":["asset:img90341b24c05219f7c4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Monteggia #/dislocation</div><div class=\"answer-line\">Transverse fracture through proximal ulnar, medially angulated</div><div class=\"answer-line\">Dislocated radial head – anterior and lateral</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Signs compartment syndrome – firm compartment, P’s – would require fasciotomy</div><div class=\"answer-line\">Radial nerve injury – wrist drop, abnormal sensation snuffbox</div><div class=\"answer-line\">Median nerve function – thumb abduction, sensation lateral palm</div><div class=\"answer-line\">Ulnar nerve function – finger abduction, sensation medial hand</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV fentanyl / morphine with doses</div><div class=\"answer-line\">IN fentanyl</div><div class=\"answer-line\">Ketamine OK IV/IM</div><div class=\"answer-line\">Accept oral but only one – paracetamol / ibuprofen / oxycodone</div><div class=\"answer-line\">Need doses wt 12kg</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Plaster for comfort – ensure pulse</div><div class=\"answer-line\">Orthopaedic referral for operative repair</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 24 year old man has been brought to the ED after attempting to jump in to a pool from a second storey balcony. He missed and landed on concrete. He is agitated and complaining of severe pelvic pain. His chest x-ray is normal. His pelvic x-ray is given below.","parts":[{"id":"a","label":"Part A","prompt":"List 2 key abnormalities and provide a classification of the injury pattern. (3 marks)\nKey abnormalities 1) 2) Classification"},{"id":"b","label":"Part B","prompt":"List 3 associated injuries including an examination finding that would support its presence. (6 marks) Associated injury Supportive examination findings An image from the right upper quadrant view of a FAST scan is provided below. A D B C"},{"id":"c","label":"Part C","prompt":"Provide labels for the arrowed structures. (4 marks) A B C D The patient has the following initial vital signs:\n\nGCS\nE3 V3 M5 Pulse 140 /min\n\nBP\n70/40 mmHg O2 sats 99% room air"},{"id":"d","label":"Part D","prompt":"State 4 key features of your fluid resuscitation of this patient. (4 marks)\n1) 2) 3) 4)"},{"id":"e","label":"Part E","prompt":"State 3 considerations when determining the utility of CT imaging for this patient.\n(3 marks) 1) 2) 3)"},{"id":"f","label":"Part F","prompt":"List 3 possible contra-indications to the use of tranexamic acid in this patient. (3 marks) 1) 2) 3)"}],"propPages":["asset:img2d99cabe9dfb795f87","asset:img18450d019def933cd4"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Vertically displaced symphysis pubis left hemipelvis</div><div class=\"answer-line\">Diastasis and vertically displaced left SI joint</div><div class=\"answer-line\">Vertical shear pelvic fracture</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Arterial injury eg internal iliac – haemorrhagic shock- tachycardia/hypotension</div><div class=\"answer-line\">Urethral injury – bruised scrotum, penile blood</div><div class=\"answer-line\">Prostate injury – high riding prostate</div><div class=\"answer-line\">Bladder rupture – haematuria</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">A – diaphragm</div><div class=\"answer-line\">B – liver</div><div class=\"answer-line\">C – right kidney</div><div class=\"answer-line\">D – free fluid/blood Morrison’s pouch</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">O neg/pos – aim for BP 80 systolic/radial pulse/mentation</div><div class=\"answer-line\">Blood products only</div><div class=\"answer-line\">Targeted coagulation management – ie ROTEM or MTP 1:1:1</div><div class=\"answer-line\">All products warm</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\">- CT will define head injury whether needs surgery – if you go straight to OT you might miss an</div><div class=\"answer-line\">operable injury</div><div class=\"answer-line\"><strong>- CTA pelvis will be required to work out whether pelvis has active bleeding and if IR is suitable </strong></div><div class=\"answer-line\">- haemodynamics – unresponsive pr deteriorating BP might make further delay in CT life-threatening</div></section><section class=\"answer-part\"><h5>Part F</h5><div class=\"answer-line\">Known pro-coagulant disorder</div><div class=\"answer-line\">Known allergy to TXA</div><div class=\"answer-line\">Longer than 3 hours since trauma</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 21 year old woman has presented to the ED with 48 hours of worsening headache. She is 32 weeks pregnant.","parts":[{"id":"a","label":"Part A","prompt":"List 4 findings on examination that would support a diagnosis of pre-eclampsia. (4 marks)\n1) 2) 3) 4) Your assessment is consistent with pre-eclampsia."},{"id":"b","label":"Part B","prompt":"List 3 investigations you would perform with justification. (3 marks)\n1) 2) 3) During your assessment, the patient begins to have a generalised seizure.\nHer vital signs are:\nPulse 110 /min\n\nBP\n180/110 mmHg O2 sats 99% 6L O2 via Hudson mask"},{"id":"c","label":"Part C","prompt":"State 5 key aspects of your management of the patient. (5 marks)\n1) 2) 3) 4) 5)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Peripheral oedema</div><div class=\"answer-line\">Visual field defects</div><div class=\"answer-line\">RUQ tenderness</div><div class=\"answer-line\">Hyper-reflexia</div><div class=\"answer-line\">Clonus</div><div class=\"answer-line\">Papilloedema</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">LFTs – raised with HELLP syndrome</div><div class=\"answer-line\">Low platelets – HELLP</div><div class=\"answer-line\">FBC – haemolysis - HELLP</div><div class=\"answer-line\">Renal function, urate – elevated common complications of per-eclampsia</div><div class=\"answer-line\">Coags – DIC can complicate pre-eclampsia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Left lateral / wedge</div><div class=\"answer-line\">Terminate seizure – midaz 5mg IV repeat if needed</div><div class=\"answer-line\"><strong>MgSO4 – 20mmol IV then infusion 5mmol/hr </strong></div><div class=\"answer-line\">BP management – hydralazine 5mg aim BP systolic &lt; 140</div><div class=\"answer-line\">Urgent O+G</div><div class=\"answer-line\">Also accept Steroids – betamethasone 11.4mg IM</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 50 year old man has presented after diving in to shallow water whilst intoxicated.\nYou are concerned he may have suffered a spinal cord injury.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table by providing the discriminatory examination findings for each clinical syndrome. (4 marks) Clinical syndrome Discriminatory examination findings Anterior cord syndrome Central cord syndrome Spinal shock Complete cord injury The patient has an isolated neck injury with weakness of both upper and lower limbs.\nHis vital signs are:\n\nGCS\nPulse /min\n\nBP\n70/40 mmHg"},{"id":"b","label":"Part B","prompt":"Name the pathophysiological phenomenon this patient is experiencing and explain the mechanism of his haemodynamic disturbance. (2 marks)"},{"id":"c","label":"Part C","prompt":"State 2 specific therapies you could employ to manage this problem. (2 marks)\n1) 2)"},{"id":"d","label":"Part D","prompt":"List 3 other complications of cervical spinal cord injury that might occur whilst the patient is in the ED. State how you would manage each complication. (3 marks) 1) 2) 3)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>Anterior cord – motor paralysis below lesion, loss temp and pain below lesion, light touch, vibration,</td><td>proprioception intact</td></tr><tr><td>Central cord – arms &gt; legs motor and sensory deficit below lesion</td><td>Spinal shock – flaccid paralysis, areflexia, absent bulbocavernosus reflex</td></tr><tr><td>Complete cord injury - flaccid paralysis, areflexia, present bulbocavernosus reflex</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Neurogenic shock – due to interruption of sympathetic supply to blood vessels and heart (lesion</div><div class=\"answer-line\">above T6)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">IV fluid – 1L N/S stat IV</div><div class=\"answer-line\">Inotropes – adren or norad infusion start 5mcg/min</div><div class=\"answer-line\">Goals systolic BP 100mmHg</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Urinary retention – insert IDC</div><div class=\"answer-line\">Hypothermia – forced warm air / external warming</div><div class=\"answer-line\">Aspiration – insert NGT, drain stomach</div><div class=\"answer-line\">Pressure areas – spinal bed, nursing cares/rolling</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"An 87 year old woman has been found on the floor at home after not having been seen for 2 days. A venous blood gas is provided below. Venous blood gas\n\npH\n7.16 (7.35 - 7.45)\n\npCO2\nmmHg (35 - 45)\n\nHCO3\nmmol/L (21 - 28)\n\nNa\n148 mmol/L (134 - 146)\n\nK\n6.9 mmol/L (3.4 - 5.0)\n\nCl\n111 mmol/L (98 - 108)","parts":[{"id":"a","label":"Part A","prompt":"Classify the major acid-base disturbance present on the venous blood gas. (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 possible diagnoses that could produce this disturbance. For each, state a feature\nfrom your assessment (history, examination or investigation) that would suggest its presence. (8 marks) Cause Assessment feature"},{"id":"c","label":"Part C","prompt":"List 2 further abnormalities on the blood gas including the likely cause of each. (2 marks) 1) 2)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">HAGMA</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Cause</th><th>Distinguishing feature</th></tr></thead><tbody><tr><td>Rhabdomyolysis – pressure areas, raised CK</td><td>Septic shock – fever, hypotension, focal source on examination eg cellulitis</td></tr><tr><td>Drug overdose – eg salicylates – empty packets found near patient</td><td>Fulminant liver failure – jaundice, hepatic flap</td></tr><tr><td>Dehydration with renal failure – raised urea/creatinine</td><td></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">- Low CO2 – hyperventilation as compensation for metabolic acidosis – close to appropriate, maybe</div><div class=\"answer-line\">not quite adequate</div><div class=\"answer-line\">- hyperkalaemia – cellular exchange for H+, due to acidosis, potentially due to renal failure or</div><div class=\"answer-line\">rhabdomyolysis</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 48 year old man has been brought to the ED with increasing confusion.\nHe has a history of chronic liver disease secondary to alcohol abuse. You are concerned about the presence of hepatic encephalopathy.","parts":[{"id":"a","label":"Part A","prompt":"List 4 differential diagnoses other than hepatic encephalopathy you would seek in this\npatient. Include a supportive finding on history or examination. (8 marks) Differential diagnosis Supportive finding (Hx, Ex) Your assessment is consistent with hepatic encephalopathy."},{"id":"b","label":"Part B","prompt":"List and justify 4 investigations you would perform. (4 marks)\n1) 2) 3) 4)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Hypoglycaemia – known diabetic, insulin use</div><div class=\"answer-line\">Alcohol intoxication / withdrawal – collateral Hx with alcohol use / abstinence</div><div class=\"answer-line\">Septic encephalopathy – fever, focal signs infection, signs meningitis eg stiff neck</div><div class=\"answer-line\">Other drug use – eg collateral Hx benzo use</div><div class=\"answer-line\">Intracranial haemorrhage – signs head trauma – unequal pupils, focal neuro signs</div><div class=\"answer-line\">Others OK</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>BSL </strong>– common cause of confusion in liver failure</div><div class=\"answer-line\">Serum Na – exclude as cause of confusion, complicating liver failure</div><div class=\"answer-line\">Serum Ammonia – confirm as cause of confusion</div><div class=\"answer-line\">Hb – exclude significant anaemia due to GI bleed</div><div class=\"answer-line\">Coag – define extent of coagulopathy / liver dysfunction</div><div class=\"answer-line\">CT head- exclude bleed in context coagulopathy</div><div class=\"answer-line\">Others OK</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 22 year old woman has presented with a fever and an altered level of consciousness after taking an unspecified overdose.","parts":[{"id":"a","label":"Part A","prompt":"Complete the table regarding the following toxidromes. (12 marks) Serotonin toxicity Anticholinergic Neuroleptic toxicity malignant syndrome Two potential agents (1/2 mark each) Neuromuscular tone Reflexes Mental status"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"4\">Check this stuff so</td></tr><tr><td><strong>(1/2 mark each) </strong></td><td>many</td><td></td><td></td></tr><tr><td><strong>Neuromuscular tone </strong></td><td>Increased tone</td><td>normal</td><td>Lead pipe rigidity</td></tr><tr><td><strong>Reflexes </strong></td><td>increased</td><td>normal</td><td>decreased</td></tr><tr><td><strong>Mental status </strong></td><td>agitation</td><td>delirium</td><td>mutism</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}];
